Here is the commit message:
Fix session-helper failing to find argyll tool.

We don't want to free the thing we're trying to return. This fixes the
bug introduced in commit b6f7c4d117a06f059a6e852e2dce8c13a3bb1f2c.

See:
  https://bugzilla.redhat.com/show_bug.cgi?id=1190720

Here is the root cause:
The bug was caused by the use of an automatic cleanup feature on the `filename` variable, which led to the premature freeing of the memory allocated for the filename string. This resulted in the session-helper being unable to return the correct filename for the argyll tool, causing it to fail to find the tool.

Here is the patch:
  **/
 static gchar *
 cd_main_find_argyll_tool (const gchar *command,
 			  GError **error)
 {
 	gboolean ret;
-	_cleanup_free_ gchar *filename = NULL;
+	gchar *filename;

 	/* try the original argyllcms filename installed in /usr/local/bin */
 	filename = g_strdup_printf ("/usr/local/bin/%s", command);
 	ret = g_file_test (filename, G_FILE_TEST_EXISTS);
 	if (ret)
 		return filename;

 	/* try the debian filename installed in /usr/bin */
 	g_free (filename);
 	filename = g_strdup_printf ("/usr/bin/argyll-%s", command);
 	ret = g_file_test (filename, G_FILE_TEST_EXISTS);
 	if (ret)
 		return filename;

 	/* try the original argyllcms filename installed in /usr/bin */
 	g_free (filename);
 	filename = g_strdup_printf ("/usr/bin/%s", command);
 	ret = g_file_test (filename, G_FILE_TEST_EXISTS);
 	if (ret)
 		return filename;

 	/* eek */
 	g_set_error (error,
 		     CD_SESSION_ERROR,
 		     CD_SESSION_ERROR_FAILED_TO_FIND_TOOL,
 		     "failed to get filename for %s", command);
 	return NULL;
 }



